mapper.select:
SELECT * FROM ( SELECT TO_CHAR(DPP.OPEN_START_DATE,'YYYY/MM/DD') ||'-'||TO_CHAR(DPP.OPEN_END_DATE,'YYYY/MM/DD') openDurationDate ,TO_CHAR(DPP.OPERATION_START_DATE,'YYYY-MM-DD') operationStartDate ,TO_CHAR(DPP.AUTO_REDEEM_DATE,'YYYY-MM-DD') autoRedeemDate ,TO_CHAR(DPP.HOLD_DAYS) holdDays ,TO_CHAR(DPP.OPEN_START_DATE,'YYYY-MM-DD') openStartDate FROM REP_PROD_INFO INFO INNER JOIN DIS_PROD_PLAN DPP ON DPP.PROD_ID = NVL(INFO.P_PROD_ID,INFO.PROD_ID) AND DPP.OPEN_START_DATE >= TO_DATE(#{announceDate},'yyyy-MM-dd')
AND DPP.OPEN_START_DATE > #{setDate}
WHERE INFO.STATUS = 'E' and DPP.DATA_STATUS = 'E' AND INFO.PROD_ID = #{prodId,jdbcType=VARCHAR} ORDER BY DPP.OPERATION_START_DATE ) WHERE ROWNUM <= 6

SELECT TO_CHAR(DPP.OPERATION_START_DATE,'YYYY-MM-DD') operationStartDate, TO_CHAR(DPP.AUTO_REDEEM_DATE,'YYYY-MM-DD') autoRedeemDate, TO_CHAR(DPP.HOLD_DAYS) holdDays, /*超额业绩报酬*/ RFF.ABOVE_AMT aboveAmt, /*超额业绩报酬-确认金额*/ RFF.AFFIRM_AMT affirmAmt, /*超额业绩报酬-确认份额*/ RFF.AFFIRM_NUM affirmNum FROM REP_PROD_INFO INFO INNER JOIN DIS_PROD_PLAN DPP ON DPP.PROD_ID = NVL(INFO.P_PROD_ID,INFO.PROD_ID) AND DPP.OPERATION_START_DATE <= TO_DATE(#{announceDate},'yyyy-MM-dd')
AND DPP.OPEN_START_DATE >= #{setDate}
/* 查询根据自动赎回日查询超额业绩报酬 */ LEFT JOIN REP_FLOAT_FEE RFF ON RFF.status = 'E' AND RFF.PROD_ID = INFO.PROD_ID AND DPP.AUTO_REDEEM_DATE = RFF.AFFIRM_DATE where INFO.STATUS = 'E' and DPP.DATA_STATUS = 'E' AND INFO.PROD_ID = #{prodId,jdbcType=VARCHAR} order by DPP.OPERATION_START_DATE desc

SELECT  TO_CHAR(ROUND(NVL(PRI.UNIT_VALUE,0),4),'FM9999999999999990.0000')  unitValue,
	   TO_CHAR(ROUND(NVL(PRI.UNIT_VALUE_T,0),4),'FM9999999999999990.0000') unitValueT
FROM REP_PROD_INFO INFO
		 INNER JOIN REP_PROD_INDEX PRI ON PRI.PROD_ID = INFO.PROD_ID AND PRI.STATUS = 'E'
WHERE INFO.PROD_ID = #{prodId}
  AND PRI.VALUE_DATE = #{lastWorkDay}
